def paintersPartition(boards: list[int], k: int) -> int:
    def countPainters(maxTime):
        painters = 1
        currentSum = 0
        for b in boards:
            if currentSum + b <= maxTime:
                currentSum += b
            else:
                painters += 1
                currentSum = b
        return painters

    low = max(boards)
    high = sum(boards)
    ans = high
    while low <= high:
        mid = (low + high) // 2
        if countPainters(mid) <= k:
            ans = mid
            high = mid - 1
        else:
            low = mid + 1
    return ans

referenceSolution.javascript:
function paintersPartition(boards, k) {
    function countPainters(maxTime) {
        let painters = 1;
        let currentSum = 0;
        for (let b of boards) {
            if (currentSum + b <= maxTime) {
                currentSum += b;
            } else {
                painters++;
                currentSum = b;
            }
        }
        return painters;
    }

    let low = Math.max(...boards);
    let high = boards.reduce((a, b) => a + b, 0);
    let ans = high;

    while (low <= high) {
        let mid = Math.floor((low + high) / 2);
        if (countPainters(mid) <= k) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }
    return ans;
}

