class Node:
    def __init__(self, val, nxt=None):
        self.val = val
        self.next = nxt

def traceCycle(head: Node):
    slow = head
    fast = head
    step = 0
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
        step += 1
        if slow == fast:
            return step
    return -1

def isFeasible(boards: list[int], k: int, max_limit: int) -> bool:
    count = 1
    current = 0
    for b in boards:
        if current + b <= max_limit:
            current += b
        else:
            count += 1
            current = b
            if count > k:
                return False
    return True

def minTime(boards: list[int], k: int) -> int:
    low = max(boards)
    high = sum(boards)
    ans = high
    while low <= high:
        mid = low + (high - low) // 2
        if isFeasible(boards, k, mid):
            ans = mid
            high = mid - 1
        else:
            low = mid + 1
    return ans

