        let mid = Math.floor((low + high) / 2);
        let count = 0;
        for (let i = 0; i < r; i++) {
            count += countLessEqual(matrix[i], mid);
        }
        if (count < required) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return low;
}

