function matrixMedian(matrix) {
    const r = matrix.length;
    const c = matrix[0].length;
    let low = Infinity;
    let high = -Infinity;
    for (let i = 0; i < r; i++) {
        if (matrix[i][0] < low) low = matrix[i][0];
        if (matrix[i][c - 1] > high) high = matrix[i][c - 1];
    }
    const required = Math.floor((r * c + 1) / 2);

    function countLessEqual(row, target) {
        let l = 0, h = row.length - 1;
        while (l <= h) {
            let m = Math.floor((l + h) / 2);
            if (row[m] <= target) l = m + 1;
            else h = m - 1;
        }
        return l;
    }

    while (low <= high) {
        let mid = Math.floor((low + high) / 2);
        let count = 0;
        for (let i = 0; i < r; i++) {
            count += countLessEqual(matrix[i], mid);
        }
        if (count < required) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return low;
}

