class Node:
    def __init__(self, val, nxt=None):
        self.val = val
        self.next = nxt

def traceCycle(head: Node):
    slow = head
    fast = head
    step = 0
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
        step += 1
        if slow == fast:
            return step
    return -1

# Approach A: Hash Map
def twoSumA(nums: list[int], target: int) -> list[int]:
    seen = {}
    for i, x in enumerate(nums):
        if target - x in seen:
            return [seen[target - x], i]
        seen[x] = i
    return []

# Approach B: Sort + Two Pointers
def twoSumB(nums: list[int], target: int) -> list[int]:
    indexed = sorted([(x, i) for i, x in enumerate(nums)])
    l, r = 0, len(nums) - 1
    while l < r:
        s = indexed[l][0] + indexed[r][0]
        if s == target:
            return [indexed[l][1], indexed[r][1]]
        elif s < target:
            l += 1
        else:
            r -= 1
    return []

