    auto countPainters = [&](long long maxTime) -> int {
        int painters = 1;
        long long currentSum = 0;
        for (int b : boards) {
            if (currentSum + b <= maxTime) {
                currentSum += b;
            } else {
                painters++;
                currentSum = b;
            }
        }
        return painters;
    };

    long long ans = high;
    while (low <= high) {
        long long mid = low + (high - low) / 2;
        if (countPainters(mid) <= k) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }
    return (int)ans;
}

