    int c = matrix[0].size();
    int low = INT_MAX, high = INT_MIN;
    for (int i = 0; i < r; i++) {
        low = min(low, matrix[i][0]);
        high = max(high, matrix[i][c - 1]);
    }
    int required = (r * c + 1) / 2;

    while (low <= high) {
        int mid = low + (high - low) / 2;
        int count = 0;
        for (int i = 0; i < r; i++) {
            count += upper_bound(matrix[i].begin(), matrix[i].end(), mid) - matrix[i].begin();
        }
        if (count < required) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return low;
}

